_VALID_NAME = re.compile(r"^[A-Za-z_][A-Za-z0-9_.']*$")


# ==============================================================================
# Problem Loader
# ==============================================================================

def load_problems(n: int = 10, seed: int = SEED) -> list:
    root = os.path.join(DATA_DIR, "miniF2F", "MiniF2F", "Valid")
    probs, seen = [], set()
    for fpath in glob.glob(os.path.join(root, "**", "*.lean"), recursive=True):
        if any(b in fpath for b in ("lake-packages", "_build", "_manual")):
            continue
        base = os.path.basename(fpath).replace(".lean", "")
        try:
            content = open(fpath, encoding="utf-8").read()
        except Exception:
            continue
        in_block = False
        lines = content.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i]
            if "/-"  in line: in_block = True
            if "-/"  in line:
                in_block = False; i += 1; continue
            if in_block or line.strip().startswith("--"):
                i += 1; continue
            m = re.match(
                r"^(?:@\[.*?\]\s*)?(?:theorem|lemma)\s+([^\s\{(:\[]+)",
                line.strip())
            if not m: i += 1; continue
            name = m.group(1).strip()
            if not _VALID_NAME.match(name): i += 1; continue
            decl_lines = [line]
            j = i + 1
            while j < len(lines) and ":=" not in "".join(decl_lines):
                decl_lines.append(lines[j]); j += 1
            decl_raw = " ".join(l.strip() for l in decl_lines)
            if ":=" in decl_raw:
                decl_raw = decl_raw[:decl_raw.index(":=")].strip()
            decl = f"theorem {name} {decl_raw.split(name,1)[-1].strip()}"
            uid  = f"valid_{base}_{name}"
            if uid not in seen:
                seen.add(uid); probs.append({"name": uid, "decl": decl})
            i = j
    probs = random.Random(seed).sample(probs, min(n, len(probs)))
    print(f"📂 Loaded {len(probs)} problems")
    return probs


# ==============================================================================
# KEY AUTODISCOVERY — run once at worker startup
# ==============================================================================

# Simple probe theorem that any working REPL solves in 1 step
_PROBE_DECL = "theorem hlp_probe (n : ℕ) : n = n"
_PROBE_MAX_STEPS = 5


def _discover_trace_key(agent) -> str:
    """
    Run the probe theorem, inspect the first trace entry, and return
    the embedding key name. Prints full diagnostic so the key is visible
    in the log for all future runs.

    Returns: key string like "embedding", "z", "state", "zt", etc.
             Returns "__raw__" if the entry is already a tensor/ndarray.
             Returns "__unknown__" if nothing is found (trace empty or new format).
    """
    try:
        result = agent.search(_PROBE_DECL, max_steps=_PROBE_MAX_STEPS)
        status = result.get("status", "?")
        trace  = result.get("trace", [])

        print(f"  [KeyDiscover] probe status={status}  trace_len={len(trace)}",
              flush=True)

        if not trace:
            # Try other top-level result keys that might hold embeddings
            print(f"  [KeyDiscover] result keys: {list(result.keys())}",
                  flush=True)
            for rk in result.keys():
                v = result[rk]
                if isinstance(v, (list, tuple)) and len(v) > 0:
                    entry = v[0]
                    if isinstance(entry, (torch.Tensor, np.ndarray)):
                        arr = (entry.detach().cpu().numpy()
                               if isinstance(entry, torch.Tensor)
                               else np.asarray(entry))
                        print(f"  [KeyDiscover] result['{rk}'][0]: "
                              f"shape={arr.shape}  norm={np.linalg.norm(arr):.4f}",
                              flush=True)
            return "__unknown__"

        entry = trace[0]
        print(f"  [KeyDiscover] trace[0] type: {type(entry).__name__}", flush=True)

        if isinstance(entry, dict):
            print(f"  [KeyDiscover] trace[0] keys: {list(entry.keys())}",
                  flush=True)
            for k, v in entry.items():
                if v is None:
                    print(f"    {k}: None", flush=True)
                    continue
                if isinstance(v, torch.Tensor):
                    arr = v.detach().cpu().numpy().flatten()
                    print(f"    {k}: Tensor  shape={arr.shape}  "
                          f"norm={np.linalg.norm(arr):.4f}  "
                          f"in_ball={np.linalg.norm(arr) < 1.0}",
                          flush=True)
                elif isinstance(v, np.ndarray):
                    arr = v.flatten()
                    print(f"    {k}: ndarray  shape={arr.shape}  "
                          f"norm={np.linalg.norm(arr):.4f}  "
                          f"in_ball={np.linalg.norm(arr) < 1.0}",
                          flush=True)
                else:
                    print(f"    {k}: {type(v).__name__} = {str(v)[:60]}",
                          flush=True)

            # Pick the key whose value is a tensor/array with norm < 1
            # (inside Poincaré ball). Fall back to first tensor key if none < 1.
            best_key = None
            first_tensor_key = None
            for k, v in entry.items():
                if isinstance(v, (torch.Tensor, np.ndarray)):
                    arr = (v.detach().cpu().numpy() if isinstance(v, torch.Tensor)
                           else np.asarray(v))
                    arr = arr.flatten()
                    if first_tensor_key is None:
                        first_tensor_key = k
                    if np.linalg.norm(arr) < 1.0:
                        best_key = k
                        break
            chosen = best_key or first_tensor_key
            print(f"  [KeyDiscover] → using key '{chosen}'", flush=True)
            return chosen or "__unknown__"

        elif isinstance(entry, (torch.Tensor, np.ndarray)):
            arr = (entry.detach().cpu().numpy() if isinstance(entry, torch.Tensor)
                   else np.asarray(entry))
            arr = arr.flatten()
            print(f"  [KeyDiscover] trace[0] raw array: "
                  f"shape={arr.shape}  norm={np.linalg.norm(arr):.4f}  "
                  f"in_ball={np.linalg.norm(arr) < 1.0}",
                  flush=True)
            return "__raw__"

        else:
            print(f"  [KeyDiscover] unexpected type: {type(entry)}  "
                  f"value={str(entry)[:80]}", flush=True)
            return "__unknown__"

    except Exception as e:
        print(f"  [KeyDiscover] probe failed: {e}", flush=True)
        return "__unknown__"


# ==============================================================================
# Trace extraction — uses discovered key
# ==============================================================================

def _extract_coords(result: dict, emb_key: str) -> list:
    """
    Extract per-step Poincaré ball embeddings from result["trace"].
    emb_key is the string returned by _discover_trace_key().
    """
    coords = []
    for step in result.get("trace", []):
        emb = None

        if emb_key == "__raw__":
            # Entry is already a tensor/ndarray
            if isinstance(step, (torch.Tensor, np.ndarray)):
                emb = step

        elif emb_key == "__unknown__":
            # Try every known key as a last resort
            if isinstance(step, dict):
                for k in ("embedding", "z", "zt", "state", "z_t",
                          "h", "hidden", "emb", "point"):
                    if step.get(k) is not None:
                        emb = step[k]; break
            elif isinstance(step, (torch.Tensor, np.ndarray)):
                emb = step

        else:
            # Use the discovered key directly
            if isinstance(step, dict):
                emb = step.get(emb_key)
            elif isinstance(step, (torch.Tensor, np.ndarray)):
                emb = step      # entry is raw — key discovery said __raw__

        if emb is None:
            continue
        if isinstance(emb, torch.Tensor):
            emb = emb.detach().cpu().numpy()
        coords.append(np.asarray(emb).flatten())

    return coords


# ==============================================================================
# Worker — spawned subprocess, mirrors benchmark_backbone._worker_backbone
# ==============================================================================

def _worker(problems: list, result_queue, max_steps: int) -> None:

    import gc

    def _send_sentinel():
        try: result_queue.put(None)
        except Exception: pass

    # ── HLP agent ─────────────────────────────────────────────────────────────
    try:
        from src.system2.lie_search import RiemannSearchAgent
        hlp_agent = RiemannSearchAgent(CKPT_PATH, MODEL_PATH, device="cuda")
        print(f"  [HLP] agent keys: {list(hlp_agent.__dict__.keys())}",
              flush=True)
        print("  ✅ HLP agent ready", flush=True)
    except Exception as e:
        import traceback
        print(f"  ❌ HLP init failed: {e}", flush=True)
        traceback.print_exc()
        _send_sentinel(); return

    # ── Discover embedding key from a live probe ───────────────────────────
    print("\n  🔍 Discovering trace embedding key...", flush=True)
    emb_key = _discover_trace_key(hlp_agent)
    print(f"  🔑 Embedding key: '{emb_key}'\n", flush=True)

    if emb_key == "__unknown__":
        print("  ❌ Could not identify embedding key. "
              "Check [KeyDiscover] output above and add the key name "
              "to _extract_coords manually.", flush=True)
        _send_sentinel(); return

    # ── Variant C agent ────────────────────────────────────────────────────────
    try:
        from src.system2.lie_search import RiemannSearchAgent
        vc_agent = RiemannSearchAgent(CKPT_PATH, MODEL_PATH, device="cuda")

        # Zero Lgeo (geodesic regularization) — paper Sec. 5.3 Variant C
        geo_zeroed = False
        for attr in ("geo_reg_weight", "geo_lambda", "geo_reg",
                     "lambda_geo", "path_reg_weight"):
            if hasattr(vc_agent, attr):
                setattr(vc_agent, attr, 0.0)
                print(f"  [VariantC] zeroed {attr}", flush=True)
                geo_zeroed = True

        if not geo_zeroed:
            # Lgeo attribute not found — print all numeric attributes
            # so user can identify the correct name
            numeric_attrs = {k: v for k, v in vc_agent.__dict__.items()
                             if isinstance(v, (int, float))}
            print(f"  [VariantC] ⚠️  No geo_reg attribute found.\n"
                  f"  Numeric attrs: {numeric_attrs}\n"
                  f"  Add the correct attribute name to the geo_zeroed loop above.",
                  flush=True)

        # Relax trust gate — mirror backbone (set first match, then break)
        for attr in ("trust_threshold", "tau"):
            if hasattr(vc_agent, attr):
                setattr(vc_agent, attr, 0.05)
                print(f"  [VariantC] relaxed {attr}=0.05", flush=True)
                break

        print("  ✅ Variant C agent ready", flush=True)
    except Exception as e:
        import traceback
        print(f"  ❌ VC init failed: {e}", flush=True)
        traceback.print_exc()
        _send_sentinel(); return

    # ── Per-problem loop ───────────────────────────────────────────────────────
    for prob in problems:
        name   = prob["name"]
        decl   = prob["decl"]
        record = {"name": name, "hlp": None, "vc": None}

        for mode, agent in [("hlp", hlp_agent), ("vc", vc_agent)]:
            holder = [None]

            def _run(ag=agent, dc=decl, ms=max_steps):
                try:
                    holder[0] = ag.search(dc, max_steps=ms)
                except Exception as ex:
                    holder[0] = {"status": f"Error:{ex}", "trace": []}

            t0     = time.time()
            thread = threading.Thread(target=_run, daemon=True)
            thread.start()
            thread.join(timeout=MAX_SECONDS_PER_PROBLEM)

            if thread.is_alive():
                status, coords = "Timeout", []
            else:
                r      = holder[0] or {}
                status = r.get("status", "Unknown")
                coords = _extract_coords(r, emb_key)

            # Hard check: reject embeddings outside the Poincaré ball
            if coords:
                norms = np.linalg.norm(np.array(coords), axis=1)
                if norms.max() >= 1.0:
                    print(f"  ⚠️  [{mode.upper()}] {name[:40]}: "
                          f"norms outside ball (max={norms.max():.3f}) — "
                          f"discarding {len(coords)} coords", flush=True)
                    coords = []
                    status = f"{status}(BadNorm)"

            elapsed = time.time() - t0
            record[mode] = {
                "status":  status,
                "time":    elapsed,
                "coords":  coords,
                "n_steps": len(coords),
            }
            print(f"  [{mode.upper()}] {name[:45]}  "
                  f"status={status}  steps={len(coords)}  t={elapsed:.1f}s",
                  flush=True)

        try:
            result_queue.put(record)
        except Exception:
            pass

        gc.collect()
        torch.cuda.empty_cache()

    _send_sentinel()


# ==============================================================================
# Visualization
# ==============================================================================

def plot_disk(ax, coords_2d, title: str, color: str) -> None:
    ax.set_aspect("equal")
    ax.add_patch(plt.Circle((0, 0), 1, fill=False,
                             linestyle="--", linewidth=0.8, color="gray"))
    ax.set_xlim(-1.15, 1.15)
    ax.set_ylim(-1.15, 1.15)
    ax.axis("off")
    ax.set_title(title, fontsize=7, pad=2)
    if len(coords_2d) < 2:
        ax.text(0, 0, "(no trace)", ha="center", va="center",
                fontsize=6, color="gray")
        return
    x, y = coords_2d[:, 0], coords_2d[:, 1]
    ax.plot(x, y, color=color, linewidth=1.2, zorder=2)
    ax.scatter(x[0],  y[0],  s=30, color="black", zorder=4, marker="o")
    ax.scatter(x[-1], y[-1], s=40, color="gold",  zorder=4, marker="*")


def generate_figures(hlp_traces: list, vc_traces: list) -> None:

    all_coords = []
    for t in hlp_traces + vc_traces:
        all_coords.extend(t["coords"])

    if not all_coords:
        print("❌ No valid coordinates — all traces empty or outside ball.")
        return

    X = np.array(all_coords)
    norms = np.linalg.norm(X, axis=1)
    print(f"\nNorm check: min={norms.min():.4f}  max={norms.max():.4f}  "
          f"all_in_ball={norms.max() < 1.0}")

    if norms.max() >= 1.0:
        print("❌ Embeddings still outside Poincaré ball after filtering.\n"
              "   Check [KeyDiscover] output — the wrong key may have been selected.")
        return

    pca   = PCA(n_components=2)
    X2    = pca.fit_transform(X)
    scale = np.percentile(np.linalg.norm(X2, axis=1), 99) or 1.0

    def tortuosity(coords_raw):
        if len(coords_raw) < 2: return float("nan")
        c2   = pca.transform(np.array(coords_raw)) / scale
        path = sum(np.linalg.norm(c2[i+1]-c2[i]) for i in range(len(c2)-1))
        geo  = np.linalg.norm(c2[-1] - c2[0])
        return path / geo if geo > 1e-6 else float("nan")

    hlp_tau  = [tortuosity(t["coords"]) for t in hlp_traces]
    vc_tau   = [tortuosity(t["coords"]) for t in vc_traces]
    hlp_mean = np.nanmean(hlp_tau)
    vc_mean  = np.nanmean(vc_tau)

    print(f"\nTortuosity  (paper target: HLP≈1.12, VC≈2.45)")
    print(f"  HLP mean: {hlp_mean:.3f}  per-problem: {[round(v,2) for v in hlp_tau]}")
    print(f"  VC  mean: {vc_mean:.3f}  per-problem: {[round(v,2) for v in vc_tau]}")
    vc_wins = sum(v > h for v, h in zip(vc_tau, hlp_tau)
                  if not (np.isnan(v) or np.isnan(h)))
    print(f"  VC > HLP: {vc_wins}/{len(hlp_traces)} problems")

    n = len(hlp_traces)
    fig, axes = plt.subplots(2, n, figsize=(max(3*n, 6), 5), squeeze=False)
    row_meta = [
        (f"HLP (Centripetal)  τ̄={hlp_mean:.2f}", hlp_traces, "#1f9f9f"),
        (f"Variant C (No Lgeo)  τ̄={vc_mean:.2f}",  vc_traces,  "#d62728"),
    ]
    for row, (label, traces, color) in enumerate(row_meta):
        axes[row, 0].set_ylabel(label, fontsize=7, rotation=90, labelpad=4)
        for col, t in enumerate(traces):
            if t["coords"]:
                c2    = pca.transform(np.array(t["coords"])) / scale
                tau_v = tortuosity(t["coords"])
                title = f"P{col+1}  {t['status']}\nτ={tau_v:.2f} ({t['n_steps']}s)"
            else:
                c2    = np.empty((0, 2))
                title = f"P{col+1}  {t['status']}"
            plot_disk(axes[row, col], c2, title, color)

    fig.suptitle(
        "Trajectory Tortuosity: HLP (Centripetal) vs Variant C (No Lgeo)\n"
        "Poincaré disk — PCA projection of hyperbolic embeddings",
        fontsize=9,
    )
    plt.tight_layout(rect=[0, 0, 1, 0.93])
    save_path = os.path.join(OUTPUT_DIR, "variant_c_vs_hlp.png")
    plt.savefig(save_path, dpi=150)
    plt.close(fig)
    print(f"\n✅ Figure saved: {save_path}")


# ==============================================================================
# Main
# ==============================================================================

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--n",         type=int, default=10)
    parser.add_argument("--max-steps", type=int, default=15)
    args = parser.parse_args()

    problems = load_problems(args.n)

    try:
        mp.set_start_method("spawn", force=True)
    except RuntimeError:
        pass

    manager      = mp.Manager()
    result_queue = manager.Queue()

    worker = mp.Process(
        target=_worker,
        args=(problems, result_queue, args.max_steps),
    )
    worker.start()

    hlp_traces, vc_traces = [], []

    while True:
        try:
            rec = result_queue.get(timeout=MAX_SECONDS_PER_PROBLEM + 30)
        except _queue.Empty:
            if not worker.is_alive():
                print("⚠️  Worker exited without sentinel.")
                break
            continue
        if rec is None:
            break
        hlp_traces.append(rec["hlp"])
        vc_traces.append(rec["vc"])
        print(f"✔ {rec['name'][:50]}"
              f"  HLP={rec['hlp']['status']}({rec['hlp']['n_steps']})"
              f"  VC={rec['vc']['status']}({rec['vc']['n_steps']})")

    worker.join(timeout=60)
    if worker.is_alive():
        worker.terminate(); worker.join()

    if not hlp_traces:
        print("❌ No traces collected.")
        return

    trace_path = os.path.join(OUTPUT_DIR, "traces.pkl")
    with open(trace_path, "wb") as f:
        pickle.dump({"hlp": hlp_traces, "vc": vc_traces}, f)
    print(f"💾 Traces saved: {trace_path}")

    generate_figures(hlp_traces, vc_traces)


if __name__ == "__main__":
    main()